-- Authorized metadata/known-source function export ONLY. No application rows; no production writes.
BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='30s';
WITH approved(name,body_sha256) AS (VALUES ('handle_new_tac_account','677689a430f370ced04cc1650e9cf0a18dd5017078f28e529db4da447ca43b16'),('has_role','381ff520625ffdb35851959e8ba5b0d4203bf734f2c3f187ce04df091f81794c'),('get_reward_status','9bd09c8524754fe2505bcf86685f3511411c6f4d894746f087b2e0d7ad75742b'),('claim_daily_reward','6b6750e5318cb5b5bc89a98a57c6fd23342eca25ef06632c41f182282735b084'),('get_tac_promo_status','19a0a744636d06f307f96445c8c707dae07e897057673124e4c123c087f86ab6'),('redeem_tac_promo','c1802672c72a032933ec567715c5222fa2f68a379cac8295023de83dbb060f13'),('get_user_reward_tasks','94c647c668e4a9969a614ad9533aaf3c6ae691b5152eedf08b61c48c483136db'),('register_my_protocol_wallet','3a23dce254ae403f9ea3af17337745f6e2b76f2324763244deeb798d4ba884e6'),('prepare_protocol_market','4fbddf8d8f154cca7f4f665c785b887b8fd037e61fbc8225e276e13c2a34a9c7'),('apply_protocol_event','8108d170622b3a504cb51d1b476015a5abe51432951fd9f09b9564737345fef8'),('get_protocol_market_feed','4bbef73cdf06f58b05f11c7c525585d5feb6c3cc7276d7026b6a617d97621303'),('get_protocol_probability_history','b07637b5e1d28eaddcc597cde2766461cafc0b9f525194002d16120f75538a5a'),('get_my_protocol_portfolio','5ebb69f64048cc4f7f7b31a72c2934c74663d50dfe66003d272e7d7358e85961'),('get_protocol_market_activity','12415484cd28260f80ecd9ac5638dc50b6fce70aa11982a4b92d1a5644ad8011'),('get_protocol_signed_orderbook','fbe0edd3f14d0115780294422b9597be1dd972f93657d18695f0f9754f725c20'),('get_protocol_metadata','121b65e260ff8a324fa16a2969c361cffeaced134eed7e0d8c87a76a6bee35ca'),('consume_protocol_wallet_link','42e0241cd4bddbd7fa213a3d91b7b419dd8cad47cb69564a5f33fb43fe143a21'),('get_my_native_reward_tasks','af7b05cf7dcf8b11ca235605d0823a0736add4e479b9829ae24beb949855e67c'),('get_my_protocol_activity','59b844ef78916cf8dae951d52c1f44744095f9df3cddbe47f6c0eaf68aa30d53'),('acquire_protocol_job_lease','e4bd20d1f9edf077b53f8568df0dad18b9d760eee81cd89f1b08a52381ccfd9f'),('renew_protocol_job_lease','2b5e0471e9ae35c7041640e43bd0621b9e335ebe2fe01c138393b5c218524a7a'),('release_protocol_job_lease','9d2d599a90a1084b7b74218dff150bf8c7c81161465ef1e24cd132dd0eb238f6'),('assert_protocol_job_lease','358fa0a26edcc44230f2a10da717daee95f87e77e97f3ab83d0ca45476171916'),('apply_leased_protocol_event','f7903bb40b64339af0524a9b30a7ad4303dc2c6b35f03f919dc9e514bdf581f1'),('advance_protocol_checkpoint','981817949215b3e98323bbfeb6fb1853e9aeb79fcdd80da03c461b88f0e40f34'),('finish_protocol_job_run','41bdb713978fdaea807f895efa68e9252d281c10e3c75d4e694bf6479ba8db0c'),('get_protocol_admin_snapshot','c9dbd580e4fb6d92a36a4b933b4b519659d70dc53ef54399fb310b8f03c82590'),('claim_market_import_run','e571e2ed1f845f3a23418973519a32dec0f1af841794e821b917be71c14529a5'),('finish_market_import_run','cce1eda5421c3e6e8756ca996f46dd4cbed3f90cc9fc4d26a2b9fbd1fdd4e03a'),('persist_market_candidates','9d791d417044efb4e04c5360c81ecf65e6bd9544518f41ee2c869ee78dfa21cd'),('get_market_previews','cfb3c92665104c6830d12a25c4c52e14016f79e6570258becc23998c87966fd8'),('get_market_import_admin','6a383b94d6eb811d726a9be2fa8fdee85ec4efd369b67ea6cd8d3cefc0e6324f'),('set_market_import_enabled','88c2ac98852759afbe8043f64bd37e37b8f6d4d7fdb0f70a6221ed616f14d444'),('review_market_candidate','274c3946b870f59f5a2e20dbb83cd87219d747487ecb4d2c83f3a834a5974d45'),('get_market_event_drafts','77b020908631476c525114581c1e594c3b71cca8f58d0fae07ed760d7633df70'),('request_market_discovery','720271c1066d02f86322f4d3c74a34d7be2b03bf5c5cbc0e01a929bf81dd9a98')),
relations AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','p','v','m','S')),
funcs AS (SELECT p.*,l.lanname,pg_get_userbyid(p.proowner) owner,pg_get_function_identity_arguments(p.oid) identity_args,
 encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') body_sha256 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.prokind='f')
SELECT jsonb_build_object(
 'mode','SCHEMA_AND_SOURCE_ALLOWLISTED_FUNCTIONS_ONLY',
 'observedAt',clock_timestamp(),'transactionReadOnly',current_setting('transaction_read_only'),
 'serverVersion',current_setting('server_version'),'migrationLedgerPresent',to_regclass('supabase_migrations.schema_migrations') IS NOT NULL,
 'schemas',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname),'[]') FROM pg_namespace WHERE nspname IN('public','auth','extensions')),
 'apiRoles',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypassRls',rolbypassrls,'inherit',rolinherit) ORDER BY rolname),'[]') FROM pg_roles WHERE rolname IN('anon','authenticated','service_role','supabase_admin','authenticator','dashboard_user')),
 'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',relname,'kind',relkind,'owner',pg_get_userbyid(relowner),'rlsEnabled',relrowsecurity,'rlsForced',relforcerowsecurity,'options',reloptions,'acl',relacl::text) ORDER BY relname),'[]') FROM relations),
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',r.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'defaultExpression',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) ORDER BY r.relname,a.attnum),'[]') FROM relations r JOIN pg_attribute a ON a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE r.relkind IN('r','p','v','m')),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',r.relname,'name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated) ORDER BY r.relname,c.conname),'[]') FROM relations r JOIN pg_constraint c ON c.conrelid=r.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',t.relname,'name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) ORDER BY t.relname,c.relname),'[]') FROM pg_index i JOIN relations t ON t.oid=i.indrelid JOIN pg_class c ON c.oid=i.indexrelid),
 'views',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',relname,'definition',pg_get_viewdef(oid,true)) ORDER BY relname),'[]') FROM relations WHERE relkind IN('v','m')),
 'enums',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',name,'labels',labels) ORDER BY name),'[]') FROM (SELECT t.typname name,jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) labels FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public' GROUP BY t.typname) q),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY tablename,policyname),'[]') FROM pg_policies WHERE schemaname='public'),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',f.proname,'identityArgs',f.identity_args,'language',f.lanname,'owner',f.owner,'securityDefiner',f.prosecdef,'config',f.proconfig,'acl',f.proacl::text,'bodySha256',f.body_sha256,'bodyMatchesReviewedSource',a.name IS NOT NULL,'definition',CASE WHEN a.name IS NOT NULL THEN pg_get_functiondef(f.oid) ELSE NULL END) ORDER BY f.proname,f.identity_args),'[]') FROM funcs f LEFT JOIN approved a ON a.name=f.proname AND a.body_sha256=f.body_sha256),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY n.nspname,c.relname,t.tgname),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND (n.nspname='public' OR (n.nspname='auth' AND c.relname IN('users','identities')))),
 'defaultAcls',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'objectType',d.defaclobjtype,'acl',d.defaclacl::text)),'[]') FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),
 'authDependencies',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull) ORDER BY c.relname,a.attnum),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE n.nspname='auth' AND c.relname IN('users','identities')),
 'productionWritesAuthorized',false,'userRowsExported',false
) AS safe_schema_export;
COMMIT;
